    if (edge.getVertices) result.vertices = edge.getVertices().map(({ x, y }) => ({ x, y }))
    if (rawRouter?.name === 'orth') result.router = 'manhattan'
    if (rawRouter?.name === 'normal' || rawRouter?.name === 'manhattan')
      result.router = rawRouter.name
